'use strict';
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',world:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',book:'<path d="M3 4h6l3 2 3-2h6v15h-6l-3 2-3-2H3Z"/><path d="M12 6v15"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8V4"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M8 5h8a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h8"/>',star:'<path d="m12 3 2.6 5.6 6.2.8-4.5 4.3 1.1 6.3-5.4-3-5.4 3 1.1-6.3L3.2 9.4l6.2-.8Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.star}</svg>`;
const STORE='orbita-platform-v2';let state;try{state=JSON.parse(localStorage.getItem(STORE))}catch{}state={name:'Алекс',theme:'forest',words:[],sessions:[],diagnostic:null,...state};let view='home',quiz=null,toastTimer,recorder,stream,audioURL;
const app=document.getElementById('app'),modal=document.getElementById('modal'),modalBody=document.getElementById('modalBody');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state))}catch{toast('Браузер не разрешил сохранить прогресс.')}}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
const routes=[['home','home','Главная'],['worlds','world','Мои тренажёры'],['path','route','Мой маршрут'],['dictionary','book','Словарик'],['results','chart','Результаты']];
function navigate(next){if(recorder?.state==='recording')stopRecording();speechSynthesis?.cancel();view=next;document.getElementById('crumb').textContent=routes.find(r=>r[0]===next)?.[2]||'Учимся читать';document.getElementById('nav').innerHTML=routes.map(([id,ic,label])=>`<button class="${id===next?'active':''}" onclick="navigate('${id}')">${icon(ic)}${label}</button>`).join('');const render={home:home,worlds:worlds,path:path,dictionary:dictionary,results:results};(render[next]||home)();window.scrollTo(0,0)}
function title(eyebrow,name,sub){return `<div class="title-row"><div><div class="eyebrow">${eyebrow}</div><h1>${name}</h1><p class="subtitle">${sub}</p></div><span class="date">${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',weekday:'long'})}</span></div>`}
const stages=['Буквы и звуки','CVC-слова','Предложения','Истории'];
function level(){if(!state.diagnostic?.passed)return 0;const completed=new Set(state.sessions.filter(s=>s.type==='cvc'&&s.passed).map(s=>s.word));if(completed.size<12)return 1;if(!state.sessions.some(s=>s.type==='sentence'&&s.passed))return 2;return 3}
function home(){const lv=level();app.innerHTML=title('Каждый день — маленькое открытие',`Привет, ${escapeHTML(state.name)} <span style="color:#c5a16a">✦</span>`,'Твой мир растёт вместе с тобой. Куда отправимся сегодня?')+`<section class="hero"><img src="assets/orbit-world.png" alt="Пушистый бирюзовый проводник с книгой на парящем острове"><div class="hero-copy"><span class="chip">${state.diagnostic?'ТВОЁ СЛЕДУЮЩЕЕ ОТКРЫТИЕ':'НАЧНЁМ БОЛЬШОЕ ПУТЕШЕСТВИЕ'}</span><h2>Большие истории<br>начинаются<br><em>с маленьких букв.</em></h2><p>${state.diagnostic?'Продолжим с того места, где тебе сейчас интереснее и полезнее. У каждого открытия свой темп.':'Давай узнаем, какие буквы и звуки ты уже знаешь. И найдём идеальный старт именно для тебя.'}</p><div class="hero-actions"><button class="primary" onclick="${(state.diagnostic||state.pendingQuiz)?'continueLearning()':'showDiagnosticIntro()'}">${(state.diagnostic||state.pendingQuiz)?'Продолжить путь':'Найти мой уровень'} <span>↗</span></button><small>${state.diagnostic?stages[lv]:'Без оценок и спешки · 5–8 мин'}</small></div></div><div class="hero-caption">✧<span><b>Твой проводник — Орби</b><small>Рядом на каждом шаге</small></span></div></section><div class="metrics"><div class="metric"><span class="metric-icon">${icon('route')}</span><div><strong>${state.sessions.length}</strong><p>занятий в твоём пути</p></div><small>Шаг за шагом</small></div><div class="metric"><span class="metric-icon">${icon('book')}</span><div><strong>${state.words.length}</strong><p>слов в копилке</p></div><small>Твои открытия</small></div><div class="metric"><span class="metric-icon">${icon('star')}</span><div><strong>${state.diagnostic?state.diagnostic.known.length:0}<span style="font-size:12px;color:#a1ad99"> / 26</span></strong><p>букв и звуков освоено</p></div></div></div><div class="section-head"><div><h2>Целый мир возможностей</h2><p>Любопытство выбирает направление. Мы помогаем расти.</p></div><button class="text-btn" onclick="navigate('worlds')">Все тренажёры &nbsp; ↗</button></div>${worldCards()}<div class="lower"><div class="panel"><h3>Твой маршрут к большим историям</h3><p>Следующий этап открывается, когда ты готов.</p><div class="steps">${stages.map((s,i)=>`<div class="step ${i===lv?'current':''}"><span>${i<lv?'✓':i+1}</span>${s}</div>`).join('')}</div></div><div class="panel school-panel"><span class="school-spark">✦</span><div class="eyebrow">ЗА ПРЕДЕЛАМИ ЭКРАНА</div><h3>Встречаемся в школе</h3><p>Открытые уроки, новые друзья<br>и ещё больше открытий.</p><button class="secondary" onclick="showSchool()">Узнать о занятиях &nbsp; ↗</button></div></div>`}
function worldCards(){return `<div class="worlds"><article class="world-card"><div class="world-art"><span class="badge">● Доступно</span><img src="assets/orbit-world.png" alt="Мир чтения с Орби"></div><div class="world-body"><div class="world-meta">АНГЛИЙСКИЙ · ЧТЕНИЕ</div><h3>От буквы к истории</h3><p>Звуки, первые слова и целые миры<br>между страницами.</p><div class="card-bottom"><span>Персональный маршрут</span><button class="round-arrow" aria-label="Открыть тренажёр чтения" onclick="navigate('path')">↗</button></div></div></article><article class="world-card"><div class="world-art sounds"><span class="badge">Следующий мир</span><span class="letter-3d">A</span><span class="letter-3d">a</span></div><div class="world-body"><div class="world-meta">НОВЫЕ НАПРАВЛЕНИЯ</div><h3>Больше способов расти</h3><p>Новые тренажёры появятся здесь.<br>Всё — в твоём общем кабинете.</p><div class="card-bottom"><span>Скоро на твоей орбите</span><span class="round-arrow">⋯</span></div></div></article><article class="world-card"><div class="world-art school"><span class="badge">Вместе со школой</span><div class="school-3d"></div></div><div class="world-body"><div class="world-meta">ЛЮДИ · УРОКИ · СОБЫТИЯ</div><h3>Учиться вместе</h3><p>Поддержка преподавателя<br>и настоящие маленькие победы.</p><div class="card-bottom"><span>Твоя школа рядом</span><button class="round-arrow" aria-label="Связаться со школой" onclick="showSchool()">↗</button></div></div></article></div>`}
function worlds(){app.innerHTML=title('Выбирай направление','Мои тренажёры','Один профиль, общая история прогресса и новые возможности.')+worldCards()}
function path(){let lv=level();app.innerHTML=title('От первого звука к самостоятельному чтению','Твой маршрут','Сначала узнаём, что уже получается. Затем двигаемся дальше по результатам.')+`<div class="paths"><div class="path"><span class="path-number">◎</span><div><h3>Находим точку старта</h3><p>Проверка всех 26 букв: отдельно название и базовый звук.</p></div><button class="${state.diagnostic?'secondary':'primary'}" onclick="showDiagnosticIntro()">${state.diagnostic?'Пройти заново':'Начать проверку'}</button></div>${stages.map((s,i)=>`<div class="path ${i>lv?'locked':''}"><span class="path-number">0${i+1}</span><div><h3>${s}</h3><p>${['Знакомимся с буквами. Слушаем, узнаём и повторяем.','Соединяем три звука: cat, sun, map. Без угадывания.','Собираем знакомые слова в короткие фразы.','Читаем короткие истории и проверяем понимание.'][i]}</p></div>${i<=lv?`<button class="primary" onclick="openStage(${i})">${i<lv?'Повторить':'Продолжить'} ↗</button>`:'<span class="locked-label">Откроется после предыдущего этапа</span>'}</div>`).join('')}</div>`}
function showModal(html){modalBody.innerHTML=html;modal.showModal()}
const alphabet='abcdefghijklmnopqrstuvwxyz'.split('');const cueWords=['apple','ball','cat','dog','egg','fish','goat','hat','insect','jam','kite','lion','moon','nest','octopus','pig','queen','rain','sun','top','up','van','web','fox','yes','zebra'];
const shuffle=a=>a.map(v=>({v,k:Math.random()})).sort((a,b)=>a.k-b.k).map(x=>x.v);
function speak(text){return speakFriendly(text);}
function continueLearning(){if(state.pendingQuiz&&!state.diagnostic){quiz=state.pendingQuiz;renderDiagnostic();return}if(!state.diagnostic){showDiagnosticIntro();return}openStage(level())}
function openStage(i){if(i>level()){toast('Сначала заверши предыдущий этап.');return}if(i===0)practiceLetters();if(i===1)startCVC();if(i===2)startSentence();if(i===3)startStory()}
function practiceLetters(index=0){const letters=state.diagnostic?alphabet.filter(l=>!state.diagnostic.known.includes(l)):alphabet;const list=letters.length?letters:alphabet;const l=list[index%list.length],word=cueWords[alphabet.indexOf(l)];app.innerHTML=`<div class="assessment"><div class="assessment-top"><button class="text-btn" onclick="navigate('path')">← Мой маршрут</button><span>Знакомство с буквами</span></div><section class="question-card"><span class="stage-tag">БУКВА И ЕЁ ЗВУК</span><div class="big-letter">${l.toUpperCase()} <span style="opacity:.45">${l}</span></div><h2>${word}</h2><p>Послушай название буквы. Потом отдельный звук.<br>Повтори вслух, когда будешь готов.</p><div class="controls"><button class="secondary" onclick="playLetterName('${l}')">Послушать букву</button><button class="secondary" onclick="playLetterSound('${l}')">Послушать звук</button></div><br><button class="primary" onclick="practiceLetters(${index+1})">Следующая буква →</button><p class="assessment-note">Повторение не повышает уровень автоматически.<br>Чтобы открыть CVC, пройди проверку после практики.</p><button class="text-btn" onclick="showDiagnosticIntro()">Проверить знания</button></section></div>`}
const cvcWords=['cat','sat','mat','map','tap','pan','pen','hen','pin','sit','dog','sun'];const wordTranslations={cat:'кот',sat:'сидел',mat:'коврик',map:'карта',tap:'кран',pan:'сковорода',pen:'ручка',hen:'курица',pin:'булавка',sit:'сидеть',dog:'собака',sun:'солнце',a:'артикль a',the:'артикль the',on:'на',is:'есть / является',happy:'счастливый'};
function startCVC(){const done=new Set(state.sessions.filter(s=>s.type==='cvc'&&s.passed).map(s=>s.word));const word=cvcWords.find(w=>!done.has(w))||cvcWords[0];quiz={type:'cvc',word};const choices=shuffle([word,...shuffle(cvcWords.filter(w=>w!==word)).slice(0,2)]);app.innerHTML=`<div class="assessment"><div class="assessment-top"><button class="text-btn" onclick="navigate('path')">← Мой маршрут</button><span>CVC · ${done.size} из 12 слов освоено</span></div><section class="question-card"><span class="stage-tag">СОЕДИНЯЕМ ТРИ ЗВУКА</span><h2>Услышь слово. Найди его.</h2><p>Послушай слово целиком. Затем выбери его среди похожих.</p><div style="margin:25px"><button class="primary" onclick="speak('${word}')">Послушать слово</button></div><div class="answers">${choices.map(w=>`<button class="answer" style="font-size:30px" onclick="answerCVC('${w}',this)">${w}</button>`).join('')}</div><p class="assessment-note">Сначала учимся узнавать слово. Затем читаем вслух и проверяем понимание.</p></section></div>`}
function answerCVC(answer,btn){document.querySelectorAll('.answer').forEach(b=>b.disabled=true);const correct=answer===quiz.word;btn.classList.add(correct?'correct':'incorrect');if(!correct){setTimeout(()=>{toast('Послушай ещё раз и попробуй снова.');startCVC()},700);return}const w=quiz.word;app.innerHTML=`<div class="assessment"><section class="question-card"><span class="stage-tag">ТЕПЕРЬ ТВОЯ ОЧЕРЕДЬ</span><div class="sound-tokens">${w.split('').map(l=>`<span class="sound-token">${l}</span>`).join('')}</div><h2>${w} <span style="color:#a3b59a;font-weight:400">— ${wordTranslations[w]}</span></h2><p>Прочитай слово вслух. Можно записать себя и прослушать.<br>Затем ответь на вопрос о значении слова.</p>${recordControls()}<div style="margin-top:22px"><button class="secondary" onclick="saveWord('${w}')">＋ В словарик</button> <button class="primary" onclick="meaningCheck('${w}')">Проверить понимание →</button></div><div class="feedback">Распознавание детского произношения ещё не подключено. Запись остаётся локальной. Здесь проверяются узнавание слова и его значение.</div></section></div>`}
function meaningCheck(w){if(recorder?.state==='recording')stopRecording();const choices=shuffle([w,...shuffle(cvcWords.filter(x=>x!==w)).slice(0,2)]);app.innerHTML=`<div class="assessment"><section class="question-card"><span class="stage-tag">ПРОВЕРЯЕМ ПОНИМАНИЕ</span><h2>Что значит «${w}»?</h2><p>Выбери подходящий перевод.</p><div class="answers">${choices.map(c=>`<button class="answer" style="font-size:16px" onclick="completeCVC('${w}','${c}',this)">${wordTranslations[c]}</button>`).join('')}</div></section></div>`}
function completeCVC(w,answer,btn){if(answer!==w){btn.classList.add('incorrect');toast('Попробуй ещё раз.');return}state.sessions.push({type:'cvc',word:w,passed:true,at:new Date().toISOString(),evidence:'recognition_and_meaning'});persist();toast('Слово освоено в заданиях на узнавание и значение.');startCVC()}
function recordControls(){return `<div class="controls"><button class="secondary" id="recordButton" onclick="toggleRecording()">◎ Записать чтение</button></div><audio id="playback" controls hidden style="width:100%;margin-top:20px"></audio><p id="recordStatus" class="assessment-note">Микрофон включится только после твоего разрешения.</p>`}
async function toggleRecording(){if(recorder?.state==='recording'){stopRecording();return}try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Запись требует HTTPS или localhost и поддерживаемый браузер.');speechSynthesis?.cancel();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});const chunks=[];const current=new MediaRecorder(stream);recorder=current;current.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};current.onstop=()=>{if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(new Blob(chunks,{type:current.mimeType}));const audio=document.getElementById('playback');if(audio){audio.src=audioURL;audio.hidden=false}const status=document.getElementById('recordStatus');if(status)status.textContent='Запись готова. Прослушай её. Аудио не отправляется на сервер.'};current.start();document.getElementById('recordButton').textContent='■ Остановить запись';document.getElementById('recordStatus').textContent='Идёт запись. Читай в своём темпе.'}catch(e){toast(e.message||'Проверь разрешение на микрофон.')}}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());const btn=document.getElementById('recordButton');if(btn)btn.textContent='◎ Записать ещё раз'}
function startSentence(){app.innerHTML=`<div class="assessment"><div class="assessment-top"><button class="text-btn" onclick="navigate('path')">← Мой маршрут</button><span>Первые предложения</span></div><section class="question-card"><span class="stage-tag">СЛОВА СТАНОВЯТСЯ ФРАЗОЙ</span><h2>Собери смысл предложения</h2><div class="reading">A cat sat on a mat.</div><div class="controls"><button class="secondary" onclick="speak('A cat sat on a mat.')">Послушать предложение</button></div><p>Кто сидел на коврике?</p><div class="answers">${['cat','dog','hen'].map(w=>`<button class="answer" style="font-size:22px" onclick="answerSentence('${w}',this)">${w}</button>`).join('')}</div><div class="feedback">Этот этап проверяет понимание предложения. Оценка самостоятельного произношения будет отдельной метрикой.</div></section></div>`}
function answerSentence(w,b){if(w!=='cat'){b.classList.add('incorrect');toast('Прочитай предложение ещё раз.');return}state.sessions.push({type:'sentence',passed:true,at:new Date().toISOString()});persist();toast('Ты понял предложение. Открываем короткие истории!');navigate('path')}
function startStory(){app.innerHTML=`<div class="assessment"><div class="assessment-top"><button class="text-btn" onclick="navigate('path')">← Мой маршрут</button><span>Короткая история</span></div><section class="question-card"><span class="stage-tag">ИСТОРИЯ · A CAT ON A MAT</span><img src="assets/orbit-world.png" alt="Орби читает книгу на волшебном острове" style="width:100%;height:210px;object-fit:cover;border-radius:18px;margin-top:22px"><div class="reading">${'A cat sat on a mat. The cat is happy.'.split(' ').map(w=>`<button onclick="wordDetail('${w.toLowerCase().replace(/\./g,'')}')">${w}</button>`).join(' ')}</div><div class="controls"><button class="secondary" onclick="speak('A cat sat on a mat. The cat is happy.')">Послушать историю</button></div><br>${recordControls()}<br><button class="primary" onclick="finishStory()">Я закончил читать →</button><div class="feedback">Нажми слово для перевода и сохранения в словарь. Картинка показывает мир Орби; иллюстрация именно к этой истории — следующий контентный этап.</div></section></div>`}
function finishStory(){if(recorder?.state==='recording')stopRecording();state.sessions.push({type:'story',passed:null,at:new Date().toISOString()});persist();toast('Практика сохранена. Автоматическая оценка речи пока недоступна.');navigate('results')}
function saveWord(w){if(!state.words.includes(w)){state.words.push(w);persist();toast('Слово в твоей копилке!')}else toast('Это слово уже в словарике.')}
function wordDetail(w){showModal(`<div class="eyebrow">ТВОЁ НОВОЕ ОТКРЫТИЕ</div><h2>${escapeHTML(w)}</h2><p>${escapeHTML(wordTranslations[w]||'Перевод готовится')}</p><div class="controls"><button class="secondary" onclick="speak('${w}')">Послушать</button><button class="primary" onclick="saveWord('${w}');modal.close()">＋ В словарик</button></div>`)}
function dictionary(){app.innerHTML=title('Слова, которые стали твоими','Мой словарик','Одна копилка для всех тренажёров. Возвращайся к открытиям в любое время.')+(state.words.length?`<div class="word-grid">${state.words.map(w=>`<article class="word-card"><span class="eyebrow">АНГЛИЙСКИЙ · ЧТЕНИЕ</span><h3>${escapeHTML(w)}</h3><p>${escapeHTML(wordTranslations[w]||'')}</p><button class="secondary" onclick="speak('${w}')">Послушать</button></article>`).join('')}</div>`:`<div class="empty"><div class="result-orb">${icon('book')}</div><h2>Соберём первые слова?</h2><p>Выбирай слова в заданиях — они будут ждать тебя здесь.</p><button class="primary" onclick="continueLearning()">Отправиться учиться ↗</button></div>`)}
function showThemes(){showModal(`<div class="eyebrow">ПРОСТРАНСТВО ТВОЕГО ВООБРАЖЕНИЯ</div><h2>Какой мир твой?</h2><p>Учебный маршрут останется твоим. Атмосферу можно менять.</p><div class="theme-options">${[['forest','✦ Летающие острова','Тёплый свет и маленькие чудеса'],['ocean','◌ Тихий океан','Свежесть, глубина и новые горизонты'],['cosmos','✧ Далёкие созвездия','Для исследователей бесконечности']].map(([id,n,d])=>`<button class="theme-option ${state.theme===id?'selected':''}" onclick="setTheme('${id}')"><b>${n}</b><br><small>${d}</small></button>`).join('')}</div>`)}
function setTheme(t){state.theme=t;document.body.className=t==='forest'?'':'theme-'+t;persist();modal.close();toast('Твой мир обновлён.')}
function showProfile(){showModal(`<div class="eyebrow">ТВОЙ ЛИЧНЫЙ МИР</div><h2>Как тебя называть?</h2><label class="field">Имя исследователя<input id="profileInput" maxlength="30" value="${escapeHTML(state.name)}" autocomplete="given-name"></label><button class="primary" onclick="saveProfile()">Сохранить</button>`)}
function saveProfile(){const n=document.getElementById('profileInput').value.trim();if(!n){toast('Напиши имя.');return}state.name=n;persist();document.getElementById('name').textContent=n;document.querySelector('.avatar').textContent=n[0].toUpperCase();modal.close();navigate(view)}
function showParent(){showModal(`<div class="eyebrow">СПОКОЙНОЕ ОБУЧЕНИЕ В СВОЁМ ТЕМПЕ</div><h2>Каждое умение<br>заслуживает внимания.</h2><p>Маршрут начинается с букв и звуков. После проверки открываются CVC-слова, затем понимание предложений и короткие истории.</p><p>В этой версии результаты хранятся на устройстве. Семейные аккаунты, серверная синхронизация и оценка детского произношения ещё не подключены.</p><button class="primary" onclick="modal.close();navigate('results')">Посмотреть результаты →</button>`)}
function showSchool(){showModal(`<div class="eyebrow">БОЛЬШЕ ОТКРЫТИЙ ВМЕСТЕ</div><h2>Ваша школа рядом.</h2><p>Здесь появятся мероприятия школы, запись на пробный урок и переход в официальный Telegram.</p><p>Контакт школы пока не указан. Кнопка станет активной после его подключения.</p><button class="secondary" onclick="modal.close()">Понятно</button>`)}
document.getElementById('name').textContent=state.name;document.querySelector('.avatar').textContent=state.name[0].toUpperCase();document.body.className=state.theme==='forest'?'':'theme-'+state.theme;window.addEventListener('pagehide',()=>{stream?.getTracks().forEach(t=>t.stop());speechSynthesis?.cancel()});
